#nullable enable // autogenerated

using PVZEngine.Buffs;
using PVZEngine.Definitions;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.lockedChestsChains)]
    public class LockedChestsChainsBuff : CurseBuffDefinition
    {
        public LockedChestsChainsBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            if (buff.Level.Energy > ENERGY_THRESOLD)
            {
                buff.Level.AddEnergy(-ENERGY_LOSE_SPEED);
            }
        }
        public const float ENERGY_THRESOLD = 500;
        public const float ENERGY_LOSE_SPEED = 1 / 15f;
    }
}
